<div class="intro-line"><p>Jumlah profil KDKMP dipisahkan dari lokasi yang terbukti terbangun dan beroperasi. Progres 100% dihitung hanya sesudah foto bukti disetujui dan status diverifikasi.</p><?php if ($can_create): ?><a class="button button-dark" href="<?= site_url('admin/kdkmp/tambah') ?>">+ Tambah KDKMP</a><?php endif; ?></div>
<div class="mini-stats"><div><span>Profil KDKMP</span><strong><?= number_format($all,0,',','.') ?></strong></div><div><span>Terbangun 100% terverifikasi</span><strong><?= number_format($completed,0,',','.') ?></strong></div><div><span>Beroperasi</span><strong><?= number_format($operating,0,',','.') ?></strong></div><div><span>Perlu pelengkapan/verval</span><strong><?= number_format($all-$completed,0,',','.') ?></strong></div></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari KDKMP</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama koperasi atau desa"></label><label><span>Kecamatan</span><select name="district"><option value="">Semua</option><?php foreach ($districts as $d): ?><option value="<?= $d['id'] ?>" <?= (string)$district===(string)$d['id']?'selected':'' ?>><?= h($d['name']) ?></option><?php endforeach; ?></select></label><label><span>Status data</span><select name="record_status"><option value="" <?= $record_status===''?'selected':'' ?>>Aktif</option><option value="arsip" <?= $record_status==='arsip'?'selected':'' ?>>Arsip</option><option value="semua" <?= $record_status==='semua'?'selected':'' ?>>Semua</option></select></label><label><span>Verifikasi</span><select name="status"><option value="">Semua</option><option value="pending" <?= $p['status']==='pending'?'selected':'' ?>>Belum diverifikasi</option><option value="verified" <?= $p['status']==='verified'?'selected':'' ?>>Terverifikasi</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Koperasi</th><th>Desa/Kelurahan</th><th>Kecamatan</th><th>Progres fisik</th><th>Verifikasi</th><th>Operasional</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['cooperative_name']) ?></strong><?php if ($r['archived_at']): ?><small class="cell-sub">Diarsipkan</small><?php endif; ?></td><td><?= h($r['village_name']) ?></td><td><?= h($r['district_name']) ?></td><td><?= $r['physical_progress']===null?'Belum dilaporkan':h(number_format($r['physical_progress'],1,',','.').'%') ?></td><td><span class="pill <?= $r['verification_status']==='verified'?'pill-green':'pill-muted' ?>"><?= $r['verification_status']==='verified'?'Terverifikasi':'Menunggu' ?></span></td><td><?= h($r['operational_status']?:'Belum dilaporkan') ?></td><td><a class="row-link" href="<?= site_url('admin/kdkmp/'.$r['id']) ?>">Buka →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7" class="empty-cell">Tidak ada KDKMP yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
